const input = $json ?? {};
const negotiationDecision = String(input.negotiation_decision ?? input.decision ?? '').toLowerCase();
const controllerStatus = String(input.controller_status ?? input.status ?? '').toLowerCase();
const dealId = input.deal_id ?? null;
const leadId = input.lead_id ?? null;
const propertyId = input.property_id ?? null;
const dynamicMao = Number(input.dynamic_mao ?? input.adjusted_mao ?? input.mao);
const counteroffer = input.counteroffer_amount == null ? null : Number(input.counteroffer_amount);
const seller = input.seller ?? {};
const dnc = Boolean(input.dnc ?? input.do_not_contact ?? false);
const blockers = Array.isArray(input.blockers) ? input.blockers : [];
const assetType = String(input.asset_type ?? input.property_type ?? 'residential').toLowerCase();
const projectedProfit = Number(input.projected_assignment_profit ?? input.projected_profit ?? 0);
const sellerName = String(seller.name ?? input.seller_name ?? '').trim();
const sellerPhone = String(seller.phone ?? input.seller_phone ?? '').trim();
const sellerEmail = String(seller.email ?? input.seller_email ?? '').trim();
const identityComplete = Boolean(dealId && leadId && propertyId);
const sellerContactComplete = Boolean(sellerPhone || sellerEmail);
const maoValid = Number.isFinite(dynamicMao) && dynamicMao > 0;
const counterofferValid = counteroffer == null || (Number.isFinite(counteroffer) && counteroffer > 0);
const hardBlock = dnc || blockers.length > 0;
let decision = 'needs_review'; let nextWorkflow = 'WF-126'; let reason = 'Incomplete or blocked negotiation decision.'; let contractReady = false; let revisedOffer = false; let reengagement = false;
if (hardBlock) { decision = dnc ? 'dnc_blocked' : 'blocked'; reason = dnc ? 'Seller is on DNC; no outbound action permitted.' : 'Active blocker prevents negotiation action.'; }
else if (!identityComplete || !sellerContactComplete || !maoValid || !counterofferValid) { decision = 'incomplete'; reason = 'Required deal, seller, MAO, or counteroffer data is missing/invalid.'; nextWorkflow = 'WF-338'; }
else if (['accepted','acceptance_ready','accepted_offer'].includes(negotiationDecision)) { decision = 'contract_decision_ready'; contractReady = true; nextWorkflow = 'WF-201'; reason = 'Seller acceptance is within the controlled negotiation state; contract launch remains human-review gated.'; }
else if (['counteroffer','counteroffer_received'].includes(negotiationDecision) && counteroffer != null) {
  if (counteroffer > dynamicMao) { decision = 'above_mao_revised_offer_or_walk_away'; revisedOffer = true; nextWorkflow = 'WF-255'; reason = 'Counteroffer exceeds dynamic MAO; autonomous acceptance is prohibited.'; }
  else if (counteroffer >= dynamicMao * 0.95) { decision = 'near_mao_controlled_review'; revisedOffer = true; nextWorkflow = 'WF-255'; reason = 'Counteroffer is at or above 95% of dynamic MAO; controlled human review required.'; }
  else { decision = 'accept_counteroffer_contract_review'; contractReady = true; nextWorkflow = 'WF-201'; reason = 'Counteroffer is below dynamic MAO and economically acceptable for contract review.'; }
}
else if (['rejected','declined'].includes(negotiationDecision)) { decision = 'rejection_reengagement'; reengagement = true; nextWorkflow = 'WF-261'; reason = 'Seller rejected the current position; route to controlled re-engagement.'; }
else if (['question','clarification','price_question'].includes(negotiationDecision)) { decision = 'clarification_response'; revisedOffer = true; nextWorkflow = 'WF-255'; reason = 'Seller needs clarification or pricing response before contract decision.'; }
else if (['timeout','no_response'].includes(negotiationDecision)) { decision = 'timeout_reengagement'; reengagement = true; nextWorkflow = 'WF-261'; reason = 'No seller response; route to controlled re-engagement.'; }
else { decision = 'needs_review'; nextWorkflow = 'WF-338'; reason = 'Negotiation decision is not recognized.'; }
const assetStrategy = { residential:'Residential wholesale economics; 70% rule is secondary reference only.', multifamily:'Multifamily economics; prioritize NOI, cap-rate/value evidence, debt/exit constraints and buyer demand.', land:'Land economics; prioritize land comps, zoning, utilities, access, topography, flood risk and development potential.', commercial:'Commercial economics; prioritize income/value evidence, tenant/lease factors, financing and exit demand.' }[assetType] ?? 'Asset-specific economics required; 70% rule is secondary reference only.';
const activity = { activity_type:'negotiation_decision_revised_offer_contract_controller', subject:'WF-339 ' + (dealId ?? 'unknown-deal'), deal_id:dealId, lead_id:leadId, property_id:propertyId, status:decision, decision, next_workflow:nextWorkflow, contract_ready:contractReady, revised_offer:revisedOffer, reengagement, dynamic_mao:dynamicMao, counteroffer_amount:counteroffer, seller_name:sellerName, seller_phone:sellerPhone, seller_email:sellerEmail, asset_type:assetType, asset_strategy:assetStrategy, projected_assignment_profit:projectedProfit, human_review_required:true, reason, hard_mao_guardrail:true, dnc, blockers };
return [{json:{...input,wf_id:'WF-339',controller_status:controllerStatus || 'evaluated',negotiation_decision:negotiationDecision,decision,next_workflow:nextWorkflow,contract_ready:contractReady,revised_offer:revisedOffer,reengagement,dynamic_mao:dynamicMao,counteroffer_amount:counteroffer,asset_type:assetType,asset_strategy:assetStrategy,human_review_required:true,hard_mao_guardrail:true,reason,crm_activity:activity,evaluated_at:new Date().toISOString()}}];
